--region public
function LimitedTimeSaleMgr:RequestCarStarGift()
    GameUtils.Request(Interfaces.CarStarGift, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local carStarGift = jsonData.carStarGift["1"]
        ---@type PlayerComponent
        local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        PlayerComponent:GetCardStarGiftDojo():Fill(carStarGift)
        Events.Broadcast("EVENT_LimitedTimeSaleMgr_CarStarGift_Requested")
    end)
end

function LimitedTimeSaleMgr:LoadAllChestVo()
    local allVo = CfUtils.GetCf(AutoIds.IdSetting6075, "TimeLimitedSaleChestVo", true)
    --按礼包顺序排序
    table.sort(allVo, function(a, b)
        return a.pos < b.pos
    end)
    return allVo
end

function LimitedTimeSaleMgr:LoadChestById(chestId)
    local chestVo = CfUtils.GetCfVo(AutoIds.IdSetting6075, "TimeLimitedSaleChestVo", chestId)
    return chestVo
end

